<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { Check, CircleAlert, Clock3, FileCheck2, ShieldCheck } from '@lucide/vue'
import { learningApi, type EvaluationSession } from '../api/client'
import SectionHeading from '../components/SectionHeading.vue'
const consentAccepted=ref(false),conditionKey=ref('METHODS'),taskKey=ref('AI_QA_TASK_1'),preScore=ref<number|null>(null),postScore=ref<number|null>(null),effort=ref<number|null>(null),feedback=ref(''),session=ref<EvaluationSession|null>(null),history=ref<EvaluationSession[]>([]),loading=ref(true),saving=ref(false),error=ref(''),notice=ref(''),elapsed=ref(0)
let timer: ReturnType<typeof setInterval>|undefined
const active=computed(()=>session.value&&!session.value.completedAt)
const elapsedText=computed(()=>Math.floor(elapsed.value/60)+'分 '+String(elapsed.value%60).padStart(2,'0')+'秒')
function updateTimer(){if(!session.value?.startedAt||session.value.completedAt)return;elapsed.value=Math.max(0,Math.floor((Date.now()-new Date(session.value.startedAt).getTime())/1000))}
async function load(){loading.value=true;try{history.value=await learningApi.evaluationSessions()}catch{error.value='评估记录暂时无法读取。'}finally{loading.value=false}}
async function start(){if(!consentAccepted.value||saving.value)return;saving.value=true;error.value='';try{session.value=await learningApi.startEvaluation({conditionKey:conditionKey.value,taskKey:taskKey.value,consentVersion:'evaluation-v1',consentAccepted:true});timer=setInterval(updateTimer,1000);notice.value='评估会话已开始，请先完成前测，再进行当前学习任务。'}catch{error.value='无法开始评估，请检查输入和服务连接。'}finally{saving.value=false}}
async function measure(phase:'PRE'|'POST'){if(!session.value||saving.value)return;const score=phase==='PRE'?preScore.value:postScore.value;if(score===null||score<0||score>100){error.value='请输入0到100之间的测验得分。';return}saving.value=true;try{await learningApi.recordEvaluationMeasurement(session.value.id,{phase,score});notice.value=(phase==='PRE'?'前测':'后测')+'已保存。'}catch{error.value='测验结果保存失败，请重试。'}finally{saving.value=false}}
async function complete(){if(!session.value||saving.value||effort.value===null||postScore.value===null){error.value='请先填写后测和心理努力评分。';return}saving.value=true;updateTimer();try{const finished=await learningApi.completeEvaluation(session.value.id,{elapsedSeconds:Math.max(1,elapsed.value),psychologicalEffort:effort.value,feedback:feedback.value});session.value=finished;history.value=[finished,...history.value.filter(item=>item.id!==finished.id)];notice.value='评估已完成，数据仅用于匿名聚合分析。';if(timer)clearInterval(timer)}catch{error.value='评估完成信息保存失败，请重试。'}finally{saving.value=false}}
function reset(){session.value=null;preScore.value=null;postScore.value=null;effort.value=null;feedback.value='';notice.value='';error.value='';consentAccepted.value=false;if(timer)clearInterval(timer)}
onMounted(()=>{void load();timer=setInterval(updateTimer,1000)});onBeforeUnmount(()=>{if(timer)clearInterval(timer)})
</script>
<template>
  <div class="page-stack evaluation-page">
    <SectionHeading eyebrow="研究评估" title="学习投入与效果记录" description="记录任务条件、前后测、任务用时和心理努力自评；这些指标分开保存，不等同于完整认知负荷测量。"><span class="evaluation-status"><ShieldCheck :size="15"/>数据按账号隔离</span></SectionHeading>
    <div v-if="error" class="inline-notice" role="alert"><CircleAlert :size="16"/>{{ error }}</div><div v-if="notice" class="inline-notice success" role="status"><Check :size="16"/>{{ notice }}</div>
    <section v-if="!session" class="content-section evaluation-consent"><div class="evaluation-icon"><ShieldCheck :size="22"/></div><div><p class="eyebrow">开始前说明</p><h2>自愿参与，结果只做聚合分析</h2><p>本模块记录你选择的实验条件、前测/后测得分、任务耗时、1–9级心理努力和可选反馈。系统不会把单次自评直接解释为认知负荷，也不会在管理员汇总中展示个人反馈原文。</p></div><div class="evaluation-form"><label>实验条件<select v-model="conditionKey"><option value="METHODS">问答方法对照</option><option value="QWEN_MATRIX">Qwen基座与LoRA对照</option><option value="LEARNING_TASK">课程学习任务</option></select></label><label>任务编号<input v-model="taskKey" maxlength="120" /></label><label class="consent-check"><input v-model="consentAccepted" type="checkbox"/>我已阅读说明并同意记录本次评估数据</label><button class="button button-dark" :disabled="!consentAccepted||saving" @click="start"><FileCheck2 :size="16"/>开始评估</button></div></section>
    <section v-else class="evaluation-workspace"><div class="evaluation-topline"><div><p class="eyebrow">{{ session.conditionKey }} · {{ session.taskKey }}</p><h2>本次评估进行中</h2></div><span class="evaluation-timer"><Clock3 :size="16"/>{{ elapsedText }}</span></div><div class="evaluation-grid"><article class="evaluation-card"><p class="eyebrow">1 · 前测</p><h3>开始学习前完成</h3><label>得分（0–100）<input v-model.number="preScore" type="number" min="0" max="100"/></label><button class="button button-outline" :disabled="saving||preScore===null" @click="measure('PRE')">保存前测</button></article><article class="evaluation-card"><p class="eyebrow">2 · 当前任务</p><h3>完成课程学习或问答任务</h3><p>可返回课程、知识图谱、练习或 AI 助教完成任务；用时由系统计时。</p><span class="task-note">当前计时：{{ elapsedText }}</span></article><article class="evaluation-card"><p class="eyebrow">3 · 后测</p><h3>完成任务后填写</h3><label>得分（0–100）<input v-model.number="postScore" type="number" min="0" max="100"/></label><button class="button button-outline" :disabled="saving||postScore===null" @click="measure('POST')">保存后测</button></article></div><section class="evaluation-card evaluation-complete"><div><p class="eyebrow">4 · 主观反馈</p><h3>心理努力自评</h3><p>1表示非常低，9表示非常高。</p></div><div class="effort-scale"><label v-for="value in 9" :key="value" :class="{selected:effort===value}"><input v-model="effort" type="radio" name="effort" :value="value"/><span>{{ value }}</span></label></div><label>可选反馈<textarea v-model="feedback" maxlength="2000" rows="3" placeholder="可以描述任务难度、证据是否有帮助或页面体验。"></textarea></label><div class="evaluation-actions"><button class="button button-outline" @click="reset">放弃本次</button><button class="button button-dark" :disabled="saving||effort===null||postScore===null" @click="complete"><Check :size="16"/>完成并保存</button></div></section></section>
    <section v-if="!loading&&history.length" class="content-section evaluation-history"><div class="section-title-row"><div><p class="eyebrow">本人记录</p><h2>最近评估会话</h2></div><span>{{ history.length }} 条</span></div><div class="evaluation-history-row" v-for="item in history" :key="item.id"><strong>{{ item.conditionKey }}</strong><span>{{ item.taskKey }}</span><span>{{ item.completedAt?'已完成':'进行中' }}</span><span v-if="item.psychologicalEffort">心理努力 {{ item.psychologicalEffort }}/9</span></div></section>
  </div>
</template>
